svg.script:
(() => {
  const blocks = document.querySelectorAll('.block');
  blocks.forEach(el => el.addEventListener('click', () => {
    blocks.forEach(b => b.classList.remove('selected'));
    el.classList.add('selected');
    document.dispatchEvent(new CustomEvent('blockselect', {
      detail: { blockId: el.dataset.block }
    }));
  }));
})();
